/* Fremec Planta · Premium
   Misma identidad visual que la versión simple (conteo de envasado y producción simple):
   barra blanca con logo a color y línea azul, fondo #F5F7FF, paneles blancos redondeados,
   pestañas subrayadas, Archivo; TV en azul noche con cian. */

:root {
  --tinta: #1A1A2E;
  --tinta-2: #333333;
  --tinta-3: #666666;
  --fondo: #F5F7FF;
  --panel: #FFFFFF;
  --panel-2: #F5F7FF;
  --hundido: #E8EFFF;
  --linea: #E1E7F5;
  --linea-2: #C3CEE8;
  --marca: #0052FF;
  --marca-osc: #003FCC;
  --marca-suave: #E8EFFF;
  --bien: #12A150;
  --bien-suave: #E3F6EB;
  --ojo: #8F4A06;
  --ojo-suave: #FBEFD9;
  --mal: #C0262D;
  --mal-suave: #FDECEC;
  --radio: 16px;
  --radio-ch: 10px;
  --sombra: 0 4px 24px rgba(0, 82, 255, .10);
  --sombra-alta: 0 24px 60px -12px rgb(0 0 0 / .25);
  --suave: cubic-bezier(.16, 1, .3, 1);
  --fuente: "Archivo", system-ui, sans-serif;
  color-scheme: light;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; font: 400 16px/1.5 var(--fuente); color: var(--tinta); background: var(--fondo); font-variant-numeric: tabular-nums; -webkit-font-smoothing: antialiased; }
::selection { background: var(--marca); color: #fff; }
img { max-width: 100%; display: block; }
a { color: var(--marca); text-underline-offset: 3px; }
h1, h2, h3 { margin: 0; line-height: 1.15; text-wrap: balance; font-stretch: 92%; }
h1 { font-size: 1.6rem; font-weight: 750; letter-spacing: -.02em; }
h2 { font-size: 1.15rem; font-weight: 700; letter-spacing: -.01em; }
p { margin: 0; }
button, input, select, textarea { font: inherit; color: inherit; }
:focus-visible { outline: 3px solid var(--marca); outline-offset: 2px; border-radius: 4px; }
[hidden] { display: none !important; }
.sub { color: var(--tinta-3); font-size: .9rem; }
.ico { width: 1.15em; height: 1.15em; flex: none; }
* { scrollbar-width: thin; scrollbar-color: var(--linea-2) transparent; }

/* ---------- barra superior (igual a la simple) ---------- */
.top { position: sticky; top: 0; z-index: 20; display: flex; align-items: center; gap: 14px; min-height: 60px; padding: 10px 20px; background: var(--panel); border-bottom: 3px solid var(--marca); box-shadow: var(--sombra); }
.marca { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--tinta); }
.marca .logo { height: 38px; width: auto; }
.marca small { font-size: .75rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--marca); background: var(--marca-suave); padding: 4px 12px; border-radius: 20px; white-space: nowrap; }
.top .sp { flex: 1; }
.prueba { font-size: .75rem; font-weight: 700; color: var(--marca); background: var(--marca-suave); letter-spacing: .08em; text-transform: uppercase; padding: 2px 8px; border-radius: 999px; }
.top .boton.fantasma { color: var(--marca); }
.top .boton.fantasma:hover { background: var(--marca-suave); }
.emp-quien { display: flex; align-items: center; gap: 10px; font-weight: 600; }

/* ---------- pestañas subrayadas ---------- */
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--linea); overflow-x: auto; overflow-y: hidden; }
.tabs a { display: flex; align-items: center; gap: 8px; padding: 12px 14px; margin-bottom: -1px; border-bottom: 2px solid transparent; color: var(--tinta-3); font-weight: 650; text-decoration: none; white-space: nowrap; }
.tabs a:hover { color: var(--tinta); }
.tabs a[aria-current] { color: var(--tinta); border-bottom-color: var(--marca); }
.tabs a .ico { opacity: .8; }
.badge { min-width: 22px; height: 22px; padding: 0 6px; border-radius: 99px; background: var(--mal); color: #fff; font-size: .78rem; font-weight: 700; display: inline-grid; place-items: center; }
.badge.n { background: var(--hundido); color: var(--tinta-2); }

/* ---------- botones ---------- */
.boton { display: inline-flex; align-items: center; justify-content: center; gap: .5em; min-height: 42px; padding: 0 16px; border: 1px solid var(--linea-2); border-radius: var(--radio-ch); background: var(--panel); color: var(--tinta); font-weight: 600; font-size: 1rem; text-decoration: none; cursor: pointer; white-space: nowrap; transition: background .15s, border-color .15s, transform .1s; }
.boton:hover { background: var(--hundido); }
.boton:active { transform: translateY(1px); }
.boton:disabled, .boton[aria-disabled="true"] { opacity: .5; cursor: not-allowed; transform: none; }
.boton.primario { background: var(--marca); border-color: var(--marca); color: #fff; }
.boton.primario:hover { background: var(--marca-osc); }
.boton.peligro { color: var(--mal); }
.boton.peligro:hover { background: var(--mal-suave); }
.boton.bien { background: var(--bien); border-color: var(--bien); color: #fff; }
.boton.fantasma { border-color: transparent; background: transparent; }
.boton.fantasma:hover { background: var(--hundido); }
.boton.chico { min-height: 34px; padding: 0 11px; font-size: .9rem; }
.boton.grande { min-height: 56px; padding: 0 24px; font-size: 1.1rem; }
.boton.ancho { width: 100%; }
.boton-icono { width: 36px; min-height: 36px; padding: 0; }

/* ---------- campos ---------- */
label { display: grid; gap: 6px; font-weight: 600; font-size: .92rem; }
input:not([type=checkbox]):not([type=radio]):not([type=file]), select, textarea { width: 100%; min-height: 46px; padding: 0 14px; border: 1px solid var(--linea-2); border-radius: var(--radio-ch); background: var(--panel); font-weight: 500; }
textarea { padding: 10px 14px; }
input::placeholder { color: #8A90A6; }
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--marca); box-shadow: 0 0 0 3px var(--marca-suave); }
input[type=checkbox] { width: 18px; height: 18px; accent-color: var(--marca); cursor: pointer; }
.grilla { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); align-items: end; }

/* ---------- avisos y pastillas ---------- */
.aviso { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--radio-ch); font-size: .95rem; font-weight: 550; }
.aviso .ico { margin-top: 2px; }
.aviso.ok { background: var(--bien-suave); color: var(--bien); }
.aviso.error, .aviso.mal { background: var(--mal-suave); color: var(--mal); }
.aviso.ojo { background: var(--ojo-suave); color: var(--ojo); }
.estado { display: inline-flex; align-items: center; gap: 6px; padding: 2px 9px; border-radius: 999px; font-size: .8rem; font-weight: 650; white-space: nowrap; background: var(--hundido); color: var(--tinta-2); }
.estado.ok { background: var(--bien-suave); color: var(--bien); }
.estado.pend, .estado.ojo { background: var(--ojo-suave); color: var(--ojo); }
.estado.mal { background: var(--mal-suave); color: var(--mal); }
.estado.azul { background: var(--marca-suave); color: var(--marca-osc); }
.chip { display: inline-block; padding: 1px 8px; border-radius: 999px; background: var(--marca-suave); color: var(--marca-osc); font-size: .78rem; font-weight: 650; }

/* ---------- barras ---------- */
.barra-p { position: relative; display: block; height: 8px; border-radius: 99px; background: var(--hundido); overflow: hidden; min-width: 60px; }
.barra-p > span { position: absolute; inset: 0 auto 0 0; border-radius: 99px; background: var(--marca); transition: width .6s var(--suave); }
.barra-p.bien > span { background: var(--bien); }
.barra-p.mal > span { background: var(--mal); }
.barra-p.gruesa { height: 12px; }
.doble-barra { position: relative; display: block; height: 8px; border-radius: 99px; background: var(--hundido); overflow: hidden; }
.doble-barra .env, .doble-barra .rem { position: absolute; inset: 0 auto 0 0; border-radius: 99px; }
.doble-barra .env { background: #9DB8FF; }
.doble-barra .rem { background: var(--marca); }
.doble-barra.excede .env { background: var(--mal); }

/* ================= INGRESO (igual a la simple) ================= */
.acceso { width: min(440px, 100%); margin: 0 auto; padding: 64px 16px; display: grid; gap: 18px; justify-items: center; }
.acceso-form { width: 100%; display: grid; gap: 14px; }
.acceso-form h1 { font-size: 1.6rem; }
.acceso-form > .sub { margin-top: -8px; font-size: 1rem; }
.acceso-caja { display: grid; gap: 14px; padding: 20px; background: var(--panel); border: 1px solid var(--linea); border-radius: var(--radio); box-shadow: var(--sombra); }
.acceso-caja .boton { margin-top: 4px; }
.acceso-pie { font-size: .9rem; color: var(--tinta-3); }

/* ================= PANEL ================= */
.lienzo { width: min(1240px, 100%); margin: 0 auto; padding: 20px 20px 64px; display: grid; gap: 22px; align-content: start; }
.encabezado { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.encabezado .sub { margin-top: 4px; }
.encabezado-acc { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }

.panel { background: var(--panel); border: 1px solid var(--linea); border-radius: var(--radio); min-width: 0; }
.panel-cab { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 14px 16px; border-bottom: 1px solid var(--linea); }
.panel-cab h2 { font-size: 1.05rem; display: flex; align-items: center; gap: 9px; }
.panel-cab h2 .ico { color: var(--marca); }
.panel-cuerpo { padding: 16px; }
.panel-pie { padding: 12px 16px; border-top: 1px solid var(--linea); }
.vacio { padding: 28px 16px; text-align: center; color: var(--tinta-3); }
.vacio strong { display: block; color: var(--tinta); margin-bottom: 4px; }

.columnas { display: grid; gap: 22px; grid-template-columns: minmax(0, 1.65fr) minmax(0, 1fr); align-items: start; }
.columnas.mitades { grid-template-columns: 1fr 1fr; }
.pila { display: grid; gap: 22px; align-content: start; min-width: 0; }

/* indicadores: tarjetas sueltas como el "resumen" de la simple */
.indicadores { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; }
.ind { padding: 14px 16px; display: grid; gap: 2px; align-content: start; background: var(--panel); border: 1px solid var(--linea); border-radius: var(--radio); text-decoration: none; color: inherit; transition: border-color .15s; }
a.ind:hover { border-color: var(--marca); }
.ind-tit { font-size: .85rem; font-weight: 600; color: var(--tinta-3); display: flex; align-items: center; gap: 7px; }
.ind-tit .ico { color: var(--marca); }
.ind-num { font-size: 2rem; font-weight: 800; line-height: 1.1; letter-spacing: -.03em; font-stretch: 88%; }
.ind-num small { font-size: 1rem; font-weight: 600; color: var(--tinta-3); margin-left: 2px; letter-spacing: 0; }
.ind-pie { font-size: .85rem; color: var(--tinta-3); }
.sube { color: var(--bien); font-weight: 650; }
.baja { color: var(--mal); font-weight: 650; }
.ind.alarma .ind-num, .ind.alarma .ind-tit .ico { color: var(--mal); }

/* tablas */
.tabla-envoltura { overflow-x: auto; }
.tabla { width: 100%; border-collapse: collapse; font-size: .95rem; }
.tabla th { text-align: left; font-size: .8rem; font-weight: 650; color: var(--tinta-3); padding: 10px 12px; border-bottom: 1px solid var(--linea); white-space: nowrap; }
.tabla td { padding: 12px; border-bottom: 1px solid var(--linea); vertical-align: middle; }
.tabla tr:last-child td { border-bottom: 0; }
.tabla tbody tr:hover td { background: #F5F7FF; }
.tabla .der { text-align: right; }
.tabla .col-check { width: 44px; padding-right: 0; }
.tabla .col-acciones { width: 1%; white-space: nowrap; text-align: right; }
.fila-link { cursor: pointer; }
.celda-barra { display: flex; align-items: center; gap: 10px; min-width: 150px; }
.celda-barra .barra-p { flex: 1; }
.celda-barra strong { min-width: 52px; text-align: right; }
.persona { display: flex; align-items: center; gap: 11px; }
.avatar { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--marca-suave); color: var(--marca-osc); font-weight: 700; font-size: .8rem; flex: none; }
.persona .sub { display: block; font-size: .82rem; }

/* menú ⋯ */
.menu { position: relative; display: inline-block; }
.menu summary { list-style: none; cursor: pointer; display: grid; place-items: center; width: 36px; height: 36px; border-radius: var(--radio-ch); color: var(--tinta-3); }
.menu summary::-webkit-details-marker { display: none; }
.menu summary:hover, .menu[open] summary { background: var(--hundido); color: var(--tinta); }
.menu-caja { position: absolute; right: 0; top: calc(100% + 4px); z-index: 10; min-width: 230px; padding: 6px; background: var(--panel); border: 1px solid var(--linea); border-radius: 12px; box-shadow: var(--sombra-alta); display: grid; gap: 2px; animation: aparecer .18s var(--suave); }
.menu-op { display: flex; align-items: center; gap: 9px; width: 100%; padding: 9px 10px; border: 0; background: none; border-radius: 8px; text-align: left; cursor: pointer; font-size: .95rem; font-weight: 550; color: var(--tinta); text-decoration: none; }
.menu-op:hover { background: var(--hundido); }
.menu-op.peligro { color: var(--mal); }
.menu-op.peligro:hover { background: var(--mal-suave); }
@keyframes aparecer { from { opacity: 0; transform: translateY(-4px); } }

/* filtros tipo pestaña dentro de una página */
.pestanas { display: flex; gap: 4px; border-bottom: 1px solid var(--linea); overflow-x: auto; overflow-y: hidden; }
.pestanas a { display: inline-flex; align-items: center; gap: 7px; padding: 10px 12px; margin-bottom: -1px; border-bottom: 2px solid transparent; color: var(--tinta-3); font-weight: 650; font-size: .95rem; text-decoration: none; white-space: nowrap; }
.pestanas a:hover { color: var(--tinta); }
.pestanas [aria-current="true"] { color: var(--tinta); border-bottom-color: var(--marca); }
.pestanas .cuenta { min-width: 22px; height: 22px; padding: 0 6px; border-radius: 99px; background: var(--hundido); color: var(--tinta-2); font-size: .78rem; display: inline-grid; place-items: center; }

/* carga de Excel */
.zona-excel { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 16px; align-items: center; padding: 16px; border-bottom: 1px solid var(--linea); }
.archivo-btn { position: relative; overflow: hidden; display: inline-flex; }
.archivo-btn input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.archivo-nombre { display: flex; align-items: center; gap: 10px; min-width: 0; color: var(--tinta-3); font-weight: 550; }
.archivo-nombre.elegido { color: var(--tinta); }
.archivo-nombre.elegido .ico { color: var(--bien); }
.check-linea { display: flex !important; flex-wrap: wrap; align-items: center; gap: 10px; font-weight: 550; padding: 12px 16px; border-bottom: 1px solid var(--linea); background: var(--panel-2); cursor: pointer; }

/* listas */
.lista { list-style: none; margin: 0; padding: 0; }
.lista > li { display: flex; gap: 12px; align-items: center; padding: 12px 16px; border-bottom: 1px solid var(--linea); }
.lista > li:last-child { border-bottom: 0; }
.lista .der { margin-left: auto; text-align: right; white-space: nowrap; }
.lista .medio { min-width: 0; }
.lista .medio .sub { display: block; overflow: hidden; text-overflow: ellipsis; }
.punto-ico { width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center; background: var(--marca-suave); color: var(--marca); flex: none; }
.punto-ico.mal { background: var(--mal-suave); color: var(--mal); }
.punto-ico.bien { background: var(--bien-suave); color: var(--bien); }
.punto-ico.ojo { background: var(--ojo-suave); color: var(--ojo); }

/* gráfico */
.grafico { width: 100%; height: auto; display: block; overflow: visible; }
.grafico text { font-family: var(--fuente); font-size: 11px; fill: var(--tinta-3); }
.grafico .col { fill: #B9CBFF; }
.grafico .col.hoy { fill: var(--marca); }
.grafico .col.b { fill: #A8E2C1; }
.grafico .col.b.hoy { fill: var(--bien); }
.grafico g:hover .col { fill: var(--marca-osc); }
.grafico g:hover .col.b { fill: #0E7D3E; }
.grafico .val { font-weight: 650; fill: var(--tinta-2); }
.leyenda { display: flex; gap: 16px; font-size: .82rem; color: var(--tinta-3); flex-wrap: wrap; }
.leyenda i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; }

.sectores { display: grid; gap: 14px; }
.sector-fila { display: grid; grid-template-columns: 160px 1fr 64px; gap: 12px; align-items: center; font-size: .95rem; }
.sector-fila strong { text-align: right; }

/* notas de venta */
.nv-fila { display: grid; grid-template-columns: 96px minmax(0, 1.3fr) minmax(190px, 1fr) 132px minmax(0, auto); gap: 18px; align-items: center; padding: 14px 16px; border-bottom: 1px solid var(--linea); }
.nv-fila:last-child { border-bottom: 0; }
.nv-num { font-weight: 750; }
.nv-num .sub { display: block; font-weight: 500; font-size: .82rem; }
.nv-cli { font-weight: 650; min-width: 0; }
.nv-cli .sub { display: block; font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nv-avance { display: grid; gap: 6px; font-size: .85rem; color: var(--tinta-3); }
.nv-avance b { color: var(--tinta); }
.nv-acc { display: flex; gap: 6px; justify-content: flex-end; flex-wrap: wrap; }
.nv-detalle { grid-column: 1 / -1; background: var(--panel-2); border: 1px solid var(--linea); border-radius: var(--radio-ch); overflow: hidden; }
.nv-detalle .tabla td { background: var(--panel); }
.nv-detalle input { max-width: 110px; min-height: 38px !important; text-align: right; }
.nv-detalle-pie { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; padding: 12px 14px; }
.fila-abierta { background: #FAFBFF; }

/* historial */
.nav-mes { display: flex; align-items: center; gap: 10px; }
.nav-mes strong { min-width: 130px; text-align: center; }
.detalle-usuario > summary { list-style: none; cursor: pointer; display: flex; justify-content: space-between; gap: 16px; align-items: center; padding: 14px 16px; }
.detalle-usuario > summary::-webkit-details-marker { display: none; }
.detalle-usuario[open] > summary { border-bottom: 1px solid var(--linea); }
.du-avance { text-align: right; display: grid; }

/* ajustes */
.ajuste { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 20px; align-items: center; padding: 16px; border-bottom: 1px solid var(--linea); }
.ajuste:last-child { border-bottom: 0; }
.ajuste h3 { font-size: 1rem; font-weight: 650; font-stretch: 100%; }
.ajuste .sub { margin-top: 3px; max-width: 64ch; }
.interruptor { position: relative; display: block; width: 44px; height: 26px; flex: none; }
.interruptor input { position: absolute; inset: 0; opacity: 0; margin: 0; width: 100%; height: 100%; cursor: pointer; z-index: 1; }
.interruptor span { position: absolute; inset: 0; border-radius: 99px; background: var(--linea-2); transition: background .2s; }
.interruptor span::after { content: ""; position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; box-shadow: 0 1px 3px rgba(0, 0, 0, .25); transition: transform .25s var(--suave); }
.interruptor input:checked + span { background: var(--marca); }
.interruptor input:checked + span::after { transform: translateX(18px); }
.interruptor input:focus-visible + span { outline: 3px solid var(--marca); outline-offset: 2px; }
.segmento { display: inline-flex; padding: 3px; border-radius: 12px; background: var(--hundido); }
.segmento label { display: block; cursor: pointer; position: relative; }
.segmento input { position: absolute; opacity: 0; pointer-events: none; }
.segmento span { display: block; padding: 7px 14px; border-radius: 9px; font-weight: 600; font-size: .92rem; color: var(--tinta-2); }
.segmento input:checked + span { background: var(--panel); color: var(--tinta); box-shadow: 0 1px 3px rgba(26, 26, 46, .14); }
.campo-chico { max-width: 90px; text-align: center; }

@media (max-width: 1100px) {
  .columnas, .columnas.mitades { grid-template-columns: 1fr; }
  .nv-fila { grid-template-columns: 84px minmax(0, 1fr) auto; }
  .nv-fila .nv-avance { grid-column: 2 / -1; }
  .nv-fila .nv-estado { grid-column: 3; grid-row: 1; }
  .nv-fila .nv-acc { grid-column: 1 / -1; justify-content: flex-start; }
}
@media (max-width: 760px) {
  .top { gap: 8px; padding: 8px 12px; }
  .top .txt, .top .prueba { display: none; }
  .marca .logo { height: 32px; }
  .tabs a { padding: 12px 10px; }
  .tabs a > span { display: none; }
  .tabs a[aria-current] > span { display: inline; }
  .lienzo { padding: 16px 12px 48px; gap: 16px; }
  .zona-excel { grid-template-columns: 1fr; }
  .sector-fila { grid-template-columns: 110px 1fr 54px; }
  .indicadores { grid-template-columns: 1fr 1fr; }
  .ajuste { grid-template-columns: 1fr; }
}

/* ================= EMPLEADO (tablet / celular) ================= */
.emp-tabs { width: min(1100px, 100%); margin: 8px auto 0; padding: 0 20px; }
.emp-tabs a { font-size: 1.05rem; padding: 14px 16px; }
.emp-cuerpo { width: min(1100px, 100%); margin: 0 auto; padding: 24px 20px 48px; display: grid; gap: 20px; align-content: start; font-size: 17px; }
.emp-titulo { display: flex; justify-content: space-between; align-items: end; gap: 16px; flex-wrap: wrap; }

.medidor { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 8px 26px; align-items: center; padding: 18px 20px; }
.medidor-num { font-size: 3.2rem; font-weight: 800; line-height: 1; letter-spacing: -.03em; font-stretch: 88%; grid-row: span 2; }
.medidor-num small { font-size: 1.3rem; color: var(--tinta-3); font-weight: 600; letter-spacing: 0; }
.medidor-txt { font-weight: 650; }
.medidor-txt.listo { color: var(--bien); }

.tarea { display: grid; grid-template-columns: 84px minmax(0, 1fr) 170px 250px 84px; gap: 18px; align-items: center; padding: 16px; border-bottom: 1px solid var(--linea); }
.tarea-cant { font-size: 1.7rem; font-weight: 800; letter-spacing: -.02em; line-height: 1; font-stretch: 90%; }
.tarea-cant small { display: block; font-size: .75rem; font-weight: 600; color: var(--tinta-3); margin-top: 4px; letter-spacing: 0; }
.tarea-prod { font-weight: 650; line-height: 1.3; min-width: 0; }
.tarea-prod .sub { display: block; font-weight: 500; margin-top: 3px; }
.tarea-estado { display: grid; gap: 6px; font-size: .9rem; }
.tarea-sumar { display: flex; gap: 8px; }
.tarea-sumar input { min-height: 52px !important; font-size: 1.3rem !important; font-weight: 750 !important; text-align: center; }
.tarea-sumar .boton { min-height: 52px; }
.tarea-fijo { justify-self: end; font-size: .78rem; font-weight: 650; color: var(--tinta-2); padding: 2px 9px; border-radius: 999px; background: var(--hundido); }
.tarea .r-borrar { justify-self: end; }
.tarea.completo { background: #F4FBF7; }
.tarea.completo .tarea-cant { color: var(--bien); }
.tarea.guardando { opacity: .55; pointer-events: none; }
.tarea-nueva { display: grid; grid-template-columns: 140px minmax(0, 1fr) auto; gap: 12px; align-items: end; padding: 16px; background: var(--panel-2); border-radius: 0 0 var(--radio) var(--radio); }

.env-grid { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 18px; align-items: start; }
.buscador { position: relative; display: block; }
.buscador .ico { position: absolute; left: 14px; top: 50%; translate: 0 -50%; color: var(--tinta-3); pointer-events: none; }
.buscador input { padding-left: 42px !important; min-height: 50px !important; font-size: 1.05rem !important; }
.pedidos { display: grid; gap: 10px; padding: 14px; max-height: 64vh; overflow-y: auto; }
.pedido { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 14px; align-items: center; width: 100%; text-align: left; padding: 14px 16px; border: 1.5px dashed var(--linea-2); border-radius: 12px; background: var(--panel); cursor: pointer; transition: border-color .15s, background .15s; }
.pedido:hover { border-color: var(--marca); }
.pedido[aria-pressed="true"] { border: 1.5px solid var(--marca); background: var(--marca-suave); }
.pedido-cli { font-weight: 700; font-size: 1.1rem; line-height: 1.2; min-width: 0; }
.pedido-cli .sub { display: block; font-weight: 500; font-size: .88rem; margin-top: 2px; }
.pedido-num { text-align: right; font-weight: 800; font-size: 1.3rem; }
.pedido-num small { display: block; font-size: .78rem; color: var(--tinta-3); font-weight: 600; }
.pedido .barra-p { grid-column: 1 / -1; }
.carga-caja { position: sticky; top: 76px; }
.carga-elegido { padding: 16px; border-bottom: 1px solid var(--linea); min-height: 88px; }
.vacio-chico { color: var(--tinta-3); display: flex; gap: 10px; align-items: center; font-weight: 550; }
.carga-elegido h3 { font-size: 1.2rem; }
.carga-items { margin: 10px 0 0; padding: 0; list-style: none; display: grid; gap: 4px; font-size: .9rem; color: var(--tinta-2); }
.carga-items li { display: flex; justify-content: space-between; gap: 10px; padding: 4px 0; border-bottom: 1px dashed var(--linea); }
.teclado { padding: 16px; display: grid; gap: 12px; }
.teclado-visor { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 6px 16px; border: 1px solid var(--linea-2); border-radius: var(--radio-ch); background: var(--panel); }
.teclado-visor output { font-size: 2.6rem; font-weight: 800; letter-spacing: -.02em; line-height: 1.2; }
.teclas { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.teclas button { min-height: 60px; border: 0; border-radius: var(--radio-ch); background: var(--hundido); font-size: 1.4rem; font-weight: 700; cursor: pointer; transition: background .1s, transform .08s; }
.teclas button:hover { background: var(--linea); }
.teclas button:active { transform: scale(.97); }
.teclas .t-borrar { font-size: 1rem; color: var(--tinta-3); }
.cliente-libre { padding: 16px; border-bottom: 1px solid var(--linea); }

.toast { position: fixed; left: 50%; bottom: 24px; z-index: 50; translate: -50% 0; display: flex; align-items: center; gap: 10px; padding: 12px 18px; border-radius: var(--radio-ch); background: var(--tinta); color: #fff; font-weight: 600; box-shadow: var(--sombra); animation: subir .35s var(--suave); max-width: calc(100vw - 32px); }
.toast.mal { background: var(--mal); }
@keyframes subir { from { opacity: 0; translate: -50% 14px; } }

@media (max-width: 980px) {
  .tarea { grid-template-columns: 70px minmax(0, 1fr) auto; gap: 12px 14px; }
  .tarea-estado { grid-column: 2 / -1; }
  .tarea-sumar, .tarea > .sub { grid-column: 1 / -1; }
  .tarea-fijo, .tarea .r-borrar { grid-column: 3; grid-row: 1; }
  .env-grid { grid-template-columns: 1fr; }
  .carga-caja { position: static; }
  .pedidos { max-height: 46vh; }
}
@media (max-width: 600px) {
  .emp-quien .txt { display: none; }
  .emp-tabs { padding: 0 8px; }
  .emp-tabs a { flex: 1; justify-content: center; }
  .emp-tabs a > span { display: inline !important; }
  .emp-cuerpo { padding: 16px 12px 40px; }
  .medidor { grid-template-columns: 1fr; }
  .medidor-num { grid-row: auto; }
  .tarea-nueva { grid-template-columns: 1fr; }
}

/* ================= PANTALLA DE PLANTA (TV, igual a la simple) ================= */
body.tv { --tv-bg: #0E0F24; --tv-panel: #1A1A2E; --tv-line: #2B2E57; --tv-ink: #F5F7FF; --tv-muted: #9EA6C9; --tv-accent: #3D7BFF; --tv-cian: #01EFFF; background: var(--tv-bg); color: var(--tv-ink); overflow: hidden; font-size: clamp(14px, 1.15vw, 22px); color-scheme: dark; }
body.tv ::selection { background: var(--tv-cian); color: var(--tv-bg); }
.tv-raiz { height: 100dvh; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 1.4em; padding: 1.6em 2em 2em; }
.tv-cab { display: flex; align-items: center; gap: 1em; }
.tv-cab .marca { font-size: 1.4em; }
.tv-cab .marca .logo { height: 2.4em; background: #fff; padding: .35em .8em; border-radius: 12px; }
.tv-cab .marca small { color: var(--tv-cian); background: rgb(1 239 255 / .1); font-size: .6em; }
.tv-cab .sp { flex: 1; }
.tv-fecha { color: var(--tv-muted); }
.tv-reloj { font-size: 2.2em; font-weight: 750; letter-spacing: -.02em; font-stretch: 90%; }
.tv-fs { background: var(--tv-panel); border: 1px solid var(--tv-line); color: var(--tv-ink); border-radius: 10px; padding: .45em .9em; font-size: .85em; font-weight: 600; cursor: pointer; display: inline-flex; gap: 8px; align-items: center; }
.tv-fs:hover { background: var(--tv-line); }
.tv-vivo { position: fixed; right: 2em; bottom: .5em; font-size: .8em; color: #6B7299; }
.tv-kpis { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1.2em; }
.tv-kpi { padding: 1.1em 1.3em 1.2em; border-radius: 14px; background: var(--tv-panel); border: 1px solid var(--tv-line); display: grid; gap: .2em; align-content: start; }
.tv-kpi strong { order: -1; font-size: 4.2em; line-height: 1; font-weight: 800; letter-spacing: -.035em; font-stretch: 88%; }
.tv-kpi span { font-size: 1.05em; color: var(--tv-muted); font-weight: 550; }
.tv-kpi em { font-style: normal; font-size: .85em; color: var(--tv-muted); }
.tv-kpi em b { color: var(--tv-cian); }
.tv-kpi em b.baja { color: #FF8A96; }
.tv-kpi.marca strong { color: var(--tv-cian); }
.tv-kpi.mal strong { color: #FF5A61; }
.tv-cuerpo { display: grid; grid-template-columns: 1.15fr 1fr; gap: 1.2em; min-height: 0; }
.tv-col { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 1.2em; min-height: 0; }
.tv-bloque { background: var(--tv-panel); border: 1px solid var(--tv-line); border-radius: 14px; padding: 1.2em 1.4em; display: flex; flex-direction: column; gap: .8em; min-height: 0; overflow: hidden; }
.tv-bloque h2 { font-size: 1.2em; font-weight: 700; display: flex; align-items: center; gap: .6em; color: var(--tv-ink); font-stretch: 100%; }
.tv-bloque h2 .ico { color: var(--tv-cian); }
.tv-bloque h2 small { margin-left: auto; color: var(--tv-muted); font-weight: 500; font-size: .75em; }
.tv-pedidos { display: grid; align-content: start; overflow: hidden; }
.tv-pedido { display: grid; grid-template-columns: 5.2em minmax(0, 1fr) 8em; gap: .25em 1em; align-items: center; padding: .55em 0; border-bottom: 1px solid var(--tv-line); }
.tv-pedido:last-child { border-bottom: 0; }
.tv-pedido .n { font-weight: 750; color: var(--tv-muted); }
.tv-pedido .c { font-weight: 650; font-size: 1.1em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tv-pedido .c small { display: block; font-size: .75em; color: var(--tv-muted); font-weight: 500; }
.tv-pedido .p { text-align: right; font-weight: 800; font-size: 1.3em; }
.tv-pedido .p small { display: block; font-size: .55em; color: var(--tv-muted); font-weight: 500; }
.tv-pedido .doble-barra { grid-column: 2; height: .5em; background: var(--tv-line); }
.tv-pedido .doble-barra .env { background: rgba(61, 123, 255, .5); }
.tv-pedido .doble-barra .rem { background: var(--tv-accent); }
.tv-pedido .doble-barra.excede .env { background: #FF5A61; }
.tv-pedido.excede .p { color: #FF8A96; }
.tv-sectores { display: grid; gap: .7em; }
.tv-sector { display: grid; grid-template-columns: 10em 1fr 4em; gap: 1em; align-items: center; font-weight: 600; }
.tv-sector .barra-p { height: .6em; background: var(--tv-line); }
.tv-sector .barra-p > span { background: var(--tv-accent); }
.tv-sector strong { text-align: right; font-size: 1.15em; font-weight: 800; }
.tv-grafico { flex: 1; min-height: 0; }
.tv-grafico svg { width: 100%; height: 100%; display: block; }
.tv-grafico text { font-family: var(--fuente); fill: var(--tv-muted); font-size: 13px; }
.tv-grafico .col { fill: #34397A; }
.tv-grafico .col.hoy { fill: var(--tv-cian); }
.tv-grafico .col.b { fill: #24456E; }
.tv-grafico .col.b.hoy { fill: var(--tv-accent); }
.tv-grafico .val { fill: var(--tv-ink); font-weight: 700; }
.tv-leyenda { display: inline-flex; gap: 1em; font-size: .9em; color: var(--tv-muted); }
.tv-leyenda i { display: inline-block; width: .7em; height: .7em; border-radius: 3px; margin-right: .4em; }
.tv-vacio { color: var(--tv-muted); padding: 1.5em 0; text-align: center; }
@media (max-width: 900px) {
  body.tv { overflow: auto; font-size: 15px; }
  .tv-raiz { height: auto; }
  .tv-kpis, .tv-cuerpo { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
